import{_ as t,o,c as r,a5 as s}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse('{"title":"Mybatis 的输出结果封装","description":"","frontmatter":{"title":"Mybatis 的输出结果封装","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","数据库","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第五部分：数据库/02-MyBatis/Mybatis 的输出结果封装.md","filePath":"posts/java快速入门/第五部分：数据库/02-MyBatis/Mybatis 的输出结果封装.md"}'),l={name:"posts/java快速入门/第五部分：数据库/02-MyBatis/Mybatis 的输出结果封装.md"};function d(u,e,i,p,c,a){return o(),r("div",null,[...e[0]||(e[0]=[s('<div><p><code>4.1 resultType</code> <strong>配置结果类型</strong></p><p><code>resultType</code></p><p>属性可以指定结果集的类型，它支持基本类型和实体类类型。 我们在前面的 <code>CRUD</code> 案例中已经对此属性进行过应用了。 需要注意的是，它和 <code>parameterType</code> 一样，如果注册过类型别名的，可以直接使用别名。没有注册过的必须 使用全限定类名。例如：我们的实体类此时必须是全限定类名（今天最后一个章节会讲解如何配置实体类的别名） 同时，当是实体类名称是，还有一个要求，实体类中的属性名称必须和查询语句中的列名保持一致，否则无法 实现封装。</p><p><code>4.1.1</code></p><p><strong>基本类型示例</strong></p><p><code>4.1.1.1 Dao</code></p><p><strong>接口</strong></p><p>/** * 查询总记录条数</p><ul><li>@return */ int findTotal(); 4.1.1.2 <strong>映射配置</strong></li></ul><p><code>\\&lt;!--</code></p><p>查询总记录条数</p><p>--&gt; &lt;select id=&quot;findTotal&quot; resultType=&quot;int&quot;&gt; select count(*) from user; &lt;/select&gt; 4.1.2 <strong>实体类类型示例</strong></p><p><code>4.1.2.1 Dao</code></p><p><strong>接口</strong></p><p>/** * 查询所有用户</p><ul><li>@return */ List&lt;User&gt; findAll(); 传智播客——专注于 <code>Java</code>、<code>.Net</code> 和 <code>Php</code>、网页平面设计工程师的培训 4.1.2.2 <code>**映射配置**</code></li></ul><p>&lt;!-- <code>配置查询所有操作</code> --&gt; &lt;select id=&quot;findAll&quot; resultType=&quot;com.itheima.domain.User&quot;&gt; select * from user &lt;/select&gt; 4.1.3 <code>**特殊情况示例**</code></p><p>4.1.3.1</p><ul><li><strong>修改实体类</strong></li><li>实体类代码如下：<code>(</code><strong>此时的实体类属性和数据库表的列名已经不一致了</strong></li></ul><p>) /** *</p><ul><li>&lt;p&gt;Title: User&lt;/p&gt;</li><li>&lt;p&gt;Description: <code>用户的实体类</code> &lt;/p&gt;</li><li>&lt;p&gt;Company: <a href="http://www.itheima.com/" target="_blank" rel="noreferrer">http://www.itheima.com/</a> &lt;/p&gt; */ public class User implements Serializable { private Integer userId; private String userName; private Date userBirthday; private String userSex; private String userAddress; public Integer getUserId() { return userId; } public void setUserId(Integer userId) { this.userId = userId; } public String getUserName() { return userName; } public void setUserName(String userName) { this.userName = userName; } public Date getUserBirthday() { return userBirthday; } public void setUserBirthday(Date userBirthday) { 传智播客——专注于 <code>Java</code>、<code>.Net</code> 和 <code>Php</code>、网页平面设计工程师的培训 this.userBirthday = userBirthday; } public String getUserSex() { return userSex; } public void setUserSex(String userSex) { this.userSex = userSex; } public String getUserAddress() { return userAddress; } public void setUserAddress(String userAddress) { this.userAddress = userAddress; } @Override public String toString() { return &quot;User [userId=&quot; + userId + &quot;, userName=&quot; + userName + &quot;, userBirthday=&quot;</li></ul><ul><li>userBirthday + &quot;, userSex=&quot;</li><li>userSex + &quot;, userAddress=&quot; + userAddress + &quot;]&quot;; } } 4.1.3.2 Dao <strong>接口</strong></li></ul><p>/** * 查询所有用户</p><ul><li>@return */ List&lt;User&gt; findAll(); 4.1.3.3 <strong>映射配置</strong></li></ul><p><code>\\&lt;!--</code></p><p>配置查询所有操作</p><p>--&gt; &lt;select id=&quot;findAll&quot; resultType=&quot;com.itheima.domain.User&quot;&gt; select * from user &lt;/select&gt; 4.1.3.4 <strong>测试查询结果</strong></p><p>@Test public void testFindAll() { 传智播客——专注于 <code>Java</code>、<code>.Net</code> 和 <code>Php</code>、网页平面设计工程师的培训 List&lt;User&gt; users = userDao.findAll(); for(User user : users) { System.out.println(user); } }</p><ul><li><strong>为什么名称会有值呢？</strong></li><li><strong>因为：</strong><code>mysql</code> <strong>在</strong> <code>windows</code> <strong>系统中不区分大小写！</strong></li></ul><p>4.1.3.5</p><ul><li><strong>修改映射配置</strong></li><li><strong>使用别名查询</strong></li></ul><p>&lt;!-- <code>配置查询所有操作</code> --&gt; &lt;select id=&quot;findAll&quot; resultType=&quot;com.itheima.domain.User&quot;&gt; select id as userId,username as userName,birthday as userBirthday, sex as userSex,address as userAddress from user &lt;/select&gt;</p><ul><li><strong>运行结果：</strong></li><li><strong>思考：</strong></li><li><strong>如果我们的查询很多，都使用别名的话写起来岂不是很麻烦，有没有别的解决办法呢？</strong></li><li><strong>请看下一小节。</strong></li></ul><p>4.2 resultMap <code>**结果类型**</code></p><p>resultMap 标签可以建立查询的列名和实体类的属性名称不一致时建立对应关系。从而实现封装。 在 <code>select</code> 标签中使用 <code>resultMap</code> 属性指定引用即可。同时 <code>resultMap</code> 可以实现将查询结果映射为复杂类 型的 <code>pojo</code>，比如在查询结果映射对象中包括 <code>pojo</code> 和 <code>list</code> 实现一对一查询和一对多查询。</p><p>4.2.1 <code>**定义**</code> resultMap &lt;!-- 建立 <code>User</code> 实体和数据库表的对应关系传智播客——专注于 <code>Java</code>、<code>.Net</code> 和 <code>Php</code>、网页平面设计工程师的培训 type 属性：指定实体类的全限定类名</p><p><code>id</code></p><p>属性：给定一个唯一标识，是给查询 <code>select</code> 标签引用用的。</p><p>--&gt; &lt;resultMap type=&quot;com.itheima.domain.User&quot; id=&quot;userMap&quot;&gt; &lt;id column=&quot;id&quot; property=&quot;userId&quot;/&gt; &lt;result column=&quot;username&quot; property=&quot;userName&quot;/&gt; &lt;result column=&quot;sex&quot; property=&quot;userSex&quot;/&gt; &lt;result column=&quot;address&quot; property=&quot;userAddress&quot;/&gt; &lt;result column=&quot;birthday&quot; property=&quot;userBirthday&quot;/&gt; &lt;/resultMap&gt; id 标签：用于指定主键字段</p><p><code>result</code></p><p>标签：用于指定非主键字段</p><p><code>column</code></p><p>属性：用于指定数据库列名</p><p><code>property</code></p><p>属性：用于指定实体类属性名称</p><p><code>4.2.2</code></p><p><strong>映射配置</strong></p><p><code>\\&lt;!--</code></p><p>配置查询所有操作</p><ul><li>--&gt;</li><li>&lt;select id=&quot;findAll&quot; resultMap=&quot;userMap&quot;&gt;</li><li>select * from user</li><li>&lt;/select&gt;</li><li>4.2.3</li></ul><p><strong>测试结果</strong></p><p>@Test public void testFindAll() { List&lt;User&gt; users = userDao.findAll(); for(User user : users) { System.out.println(user); } } **运行结果：**传智播客——专注于 <code>Java</code>、<code>.Net</code> 和 <code>Php</code>、网页平面设计工程师的培训 `</p></div>',1)])])}const q=t(l,[["render",d]]);export{g as __pageData,q as default};
